fn axis_xx() void { set_axis(true); }

// ---------------------------------------------------------------- (arf)
// ARF (codegen Variant::arf; docs/cerebras-8b-speed.md 9.5 / 10, ar_probe2 levels
// 18): the Y axis's full all-reduces as streamed halves with dual-input merges.
// Root R = PY / 2; each half in groups of ARG rows counted outward from R (k =
// |py - R|, group q = (k - 1) / ARG); a one-way level-1 chain inside each group
// into its end (k = q ARG + 1), the ends' one-way level-2 chain into R. R merges
// the two halves word by word through a FIFO and takes its own copy over a
// loop-back. Every non-root send is async; the broadcast is drained by a
// concurrent blocking receive (a word of d is read before the result word that
// replaces it can arrive). On the Y axis the queues are bound by role (iq3 the
// level-1 input, oq4 the level-1 output, iq5 the level-2 input, oq6 the level-2
// output; R: iq5 north, iq6 south), so one op serves both colour parities; X
// keeps the default bindings. The host writes the Y route words and each PE's role
// (rcfg, 12 words a PE: serve8b_region.rs route_words_arf).
const ARF: u16 = 1;
const ARG_SH: u16 = 3;
const ARG: u16 = 1 << ARG_SH;
var arf_fifo_buf = @zeros([32]f32);
const arf_fifo = @allocate_fifo(arf_fifo_buf);
const arf_ua = @get_ut_id(3);
const arf_ub = @get_ut_id(4);
var hy_root: bool = false;
var hy_kk: u16 = 0;       // 1-based position in the group, 1 = its end
var hy_gs: u16 = 0;       // this group's size (the farthest may be partial)
var hy_far: bool = false; // in the farthest group
// The six queues' config words (iq3, oq4, iq5, oq6, iq6, iq4): [0..6) on the Y
// axis, [6..12) on X (the defaults).
var hy_qv = @zeros([12]u16);
const IQR = tile_config.input_queue_config.in_queue_addr_range;
const OQR = tile_config.output_queue_config.out_queue_addr_range;
const a_iq3 = tile_config.input_queue_config.get_input_queue_config_addr(3);
const a_iq4 = tile_config.input_queue_config.get_input_queue_config_addr(4);
const a_iq5 = tile_config.input_queue_config.get_input_queue_config_addr(5);
const a_iq6 = tile_config.input_queue_config.get_input_queue_config_addr(6);
const a_oq4 = tile_config.output_queue_config.get_output_queue_config_addr(4);
const a_oq6 = tile_config.output_queue_config.get_output_queue_config_addr(6);
// Before the axis's routes: output queues 4 and 6 empty, then the bindings.
fn arf_qcols(x: bool) void {
  while ((tile_config.output_queue_status.get_raw() & 0x5000) != 0x5000) {}
  const o: u16 = if (x) 6 else 0;
  @set_config(a_iq3, hy_qv[o], IQR);
  @set_config(a_oq4, hy_qv[o + 1], OQR);
  @set_config(a_iq5, hy_qv[o + 2], IQR);
  @set_config(a_oq6, hy_qv[o + 3], OQR);
  @set_config(a_iq6, hy_qv[o + 4], IQR);
  @set_config(a_iq4, hy_qv[o + 5], IQR);
}
// The host's role word (serve8b_region.rs route_words_arf) -> the Y bindings.
fn arf_setup() void {
  const w = rcfg[2 * NCOL + 1];
  hy_root = (w & 1) != 0;
  hy_far = (w & 2) != 0;
  hy_kk = @as(u16, (w >> 4) & 0xff);
  hy_gs = @as(u16, (w >> 12) & 0xff);
  const r1 = (w & 4) != 0;
  const s2 = (w & 8) != 0;
  const c10: u16 = @get_int(c_r1_0);
  const c11: u16 = @get_int(c_r1_1);
  const c20: u16 = @get_int(c_r2_0);
  const c21: u16 = @get_int(c_r2_1);
  const b_i3: u16 = @get_config(a_iq3, IQR) & 0xffe0;
  const b_i4: u16 = @get_config(a_iq4, IQR) & 0xffe0;
  const b_i5: u16 = @get_config(a_iq5, IQR) & 0xffe0;
  const b_i6: u16 = @get_config(a_iq6, IQR) & 0xffe0;
  const b_o4: u16 = @get_config(a_oq4, OQR) & 0xfe0f;
  const b_o6: u16 = @get_config(a_oq6, OQR) & 0xfe0f;
  hy_qv[6] = b_i3 | c10; hy_qv[7] = b_o4 | (c11 << 4); hy_qv[8] = b_i5 | c20;
  hy_qv[9] = b_o6 | (c21 << 4); hy_qv[10] = b_i6 | c21; hy_qv[11] = b_i4 | c11;
  // Y: iq3 the level-1 input, oq4 the level-1 output, iq5 the level-2 input
  // (the root: north), oq6 the level-2 output, iq6 parked (the root: south),
  // iq4 parked, on colour 16 (C_Q2: nothing routes it to a ramp; 11 and 12 are
  // the handoffs' C_R0 / C_R1, which hung 0496).
  hy_qv[0] = b_i3 | (if (r1) c11 else c10);
  hy_qv[1] = b_o4 | ((if (r1) c10 else c11) << 4);
  hy_qv[2] = b_i5 | (if (hy_root) c20 else if (s2) c20 else c21);
  hy_qv[3] = b_o6 | ((if (s2) c21 else c20) << 4);
  hy_qv[4] = b_i6 | (if (hy_root) c21 else 16);
  hy_qv[5] = b_i4 | 16;
}
// Sum of d over the Y axis, left in d on every PE.
fn arf_ar(d: mem1d_dsd, n: u16) void {
  const A = .{ .async = true, .ut_id = arf_ub };
  if (hy_root) {
    @fadds(arf_fifo, fin(q_r2_1_in, n), d, .{ .async = true, .ut_id = arf_ua });
    @fadds(fout(q_bc_out, n), fin(q_r2_0_in, n), arf_fifo, A);
  } else if (hy_kk > 1) {
    // a level-1 member: the group's start sends, the others add-forward
    if (hy_kk == hy_gs) { @fmovs(fout(q_r1_1_out, n), d, A); }
    else { @fadds(fout(q_r1_1_out, n), fin(q_r1_0_in, n), d, A); }
  } else if (hy_far) {
    // the farthest group's end turns its level-1 stream into the level-2 stream
    if (hy_gs == 1) { @fmovs(fout(q_r2_1_out, n), d, A); }
    else { @fadds(fout(q_r2_1_out, n), fin(q_r1_0_in, n), d, A); }
  } else {
    // a group end: its level-1 input and the level-2 stream at once (level 1 through the FIFO)
    @fadds(arf_fifo, fin(q_r1_0_in, n), d, .{ .async = true, .ut_id = arf_ua });
    @fadds(fout(q_r2_1_out, n), fin(q_r2_0_in, n), arf_fifo, A);
  }
  @fmovs(d, fin(q_bc_in, n));
}

fn allreduce(is_max: bool, buf: mem1d_dsd, n: u16) void {
  if ((ARF & 1) != 0 and !axis_x) { arf_ar(buf, n); return; }   // (arf)
  phase1(is_max, buf, n);

if (HROUTE == 0) { route_gbcast(); }
if ((ARF & 1) != 0) { arf_setup(); }   // (arf) before the first axis_y
axis_y();

old:
oq_drain();
var i: u16 = 0;
while (i < NCOL) : (i += 1) { put_route(caddr[i], rcfg[(if (x) 0 else NCOL) + i]); }

new:
oq_drain();
if ((ARF & 1) != 0) { arf_qcols(x); }   // (arf) the queues' bindings before the routes
var i: u16 = 0;
while (i < NCOL) : (i += 1) { put_route(caddr[i], rcfg[(if (x) 0 else NCOL) + i]); }
